// Package protocol holds the LSP 3.17 types GoHard's language server
// speaks (#25). protocol_gen.go is generated by tools/genprotocol from
// the vendored metaModel.json: only the closure of the methods the
// server handles or sends (tools/genprotocol/gen.Methods), with the
// mapping described in tools/genprotocol/gen.
//
// Encoding is deterministic (P1): struct fields are written in model
// order, maps with sorted keys (encoding/json), LSPAny values as their
// raw bytes, and nil required lists as []. An or type ("A | B") is a
// struct with one field, Value, holding a value (never a pointer) of
// one alternative type; reading picks the alternative whose JSON kind
// matches and, between object alternatives, the one whose required
// keys are all present and that knows the most keys of the object,
// the first in model order on a tie. Reading never panics; JSON that
// fits no alternative is an error.
package protocol

//go:generate go run ../../tools/genprotocol -root ../..

// Ptr returns a pointer to a copy of v, for optional fields:
// Version: protocol.Ptr[int32](3).
func Ptr[T any](v T) *T { return &v }
